import random,sys,itertools
sys.path.insert(0,'/workspace/submission')
import main as M

def naive_classes(n,A,trans,accept):
    block=[1 if accept[s] else 0 for s in range(n)]
    while True:
        sig={}; nb=[0]*n; nxt=0
        for s in range(n):
            key=(block[s],tuple(block[trans[s][c]] for c in range(A)))
            if key not in sig: sig[key]=nxt; nxt+=1
            nb[s]=sig[key]
        if nb==block: return len(set(block))
        block=nb

def ev(e,w):
    op=e['op']
    if op=='true': return True
    if op=='false': return False
    if op=='match': return list(w)==list(e['path'])
    if op=='startswith': return list(w[:len(e['path'])])==list(e['path'])
    if op=='endswith':
        p=list(e['path']); return len(w)>=len(p) and list(w[len(w)-len(p):])==p
    if op=='contains':
        p=list(e['path']); ww=list(w)
        if len(p)==0: return True
        return any(ww[i:i+len(p)]==p for i in range(len(ww)-len(p)+1))
    if op=='not': return not ev(e['arg'],w)
    if op=='and': return all(ev(a,w) for a in e['args'])
    if op=='or': return any(ev(a,w) for a in e['args'])

def rand_expr(tokens,depth):
    choices=['true','false','match','startswith','endswith','contains'] if depth<=0 else \
            ['true','false','match','startswith','endswith','contains','not','and','or']
    op=random.choice(choices)
    if op in ('true','false'): return {'op':op}
    if op in ('match','startswith','endswith','contains'):
        return {'op':op,'path':[random.choice(tokens) for _ in range(random.randint(0,3))]} if tokens else {'op':op,'path':[]}
    if op=='not': return {'op':'not','arg':rand_expr(tokens,depth-1)}
    return {'op':op,'args':[rand_expr(tokens,depth-1) for _ in range(random.randint(0,3))]}

random.seed(123)
for trial in range(800):
    A=random.randint(0,3); tokens=[f"t{i}" for i in range(A)]
    rules=[]
    for _ in range(random.randint(0,3)): rules.append({'action':'allow','when':rand_expr(tokens,2)})
    for _ in range(random.randint(0,3)): rules.append({'action':'drop','when':rand_expr(tokens,2)})
    req={'services':tokens,'rules':rules,'queries':[]}
    try: res=M.compile_bundle(req)
    except M.WireError as e:
        continue
    d=res['dfa']; n=len(d['accept']); tr=d['next']; acc=d['accept']
    cls=naive_classes(n,A,tr,acc)
    assert cls==n,(trial,"not minimal",n,cls,req)
print("all outputs minimal across random requests")
